regras.b1.02.001:
:host {
  display: block;
  width: 100%;
  color: var(--text, #172033);
  font-family: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;
}

regras.b1.03.001:
.app-header {
  min-height: 62px; display: grid; grid-template-columns: 42px 1fr auto; gap: 10px;
  align-items: center; padding: 8px 14px; background: var(--primary); color: #fff;
  box-shadow: 0 4px 14px rgba(16,35,63,.18);
}

regras.b1.07.001:
.prototype-drawer {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: none;
}

regras.b1.07.003:
.drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: rgba(7, 16, 30, .60);
}

regras.b1.07.004:
.drawer-panel {
  position: absolute;
  inset: 0 auto 0 0;
  width: min(80vw, 360px);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #3b4a7d;
  color: #fff;
  box-shadow: 12px 0 30px rgba(0, 0, 0, .32);
}

regras.b1.07.005:
.drawer-top {
  flex: 0 0 auto;
  min-height: 106px;
  padding: 30px 22px 20px;
  display: flex;
  align-items: center;
}

regras.b1.07.006:
.drawer-identity {
  min-width: 0;
  display: flex;
  gap: 14px;
  align-items: center;
}

regras.b1.07.007:
.drawer-avatar {
  flex: 0 0 56px;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border: 2px solid rgba(255, 255, 255, .20);
  border-radius: 50%;
  background: #dbeafe;
  color: #1e3a8a;
  font-size: 20px;
  font-weight: 800;
}

regras.b1.07.010:
.drawer-profile strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 16px;
  font-weight: 600;
}

regras.b1.07.011:
.drawer-profile small {
  margin-top: 2px;
  color: #bfdbfe;
  font-size: 11px;
  font-weight: 400;
  text-transform: lowercase;
}

regras.b1.07.012:
.drawer-online {
  flex: 0 0 auto;
  width: calc(100% - 44px);
  margin: 0 22px 10px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 10px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, .08);
  color: #fff;
  text-align: left;
  cursor: pointer;
}

regras.b1.07.016:
.online-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 0 4px rgba(74, 222, 128, .14);
}

regras.b1.07.022:
.drawer-nav {
  flex: 1 1 auto;
  min-height: 0;
  display: block;
  margin: 0;
  padding: 0 0 8px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, .35) transparent;
}

regras.b1.07.025:
.drawer-nav button {
  width: 100%;
  min-height: 51px;
  padding: 14px 22px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, .10);
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 15px;
  align-items: center;
  text-align: left;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
}

regras.b1.07.028:
.drawer-footer {
  flex: 0 0 auto;
  margin-top: 0;
  padding: 16px 22px 30px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  background: rgba(0, 0, 0, .10);
}

regras.b1.07.030:
.drawer-logout {
  min-height: 32px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 14px;
  cursor: pointer;
}

regras.b1.07.033:
.drawer-emergency {
  min-height: 41px;
  border: 1px solid rgba(255, 255, 255, .54);
  border-radius: 999px;
  background: transparent;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
